import { computeSignature, SignatureError, verifyWebhook } from "../src/verify.ts";

const SECRET = "current-test-secret";
const OLD_SECRET = "previous-test-secret";
const POLICY = { auto_approve_max_minor: 500_000, auto_approve_currencies: ["INR"] };
function event(id: string, type = "refund.requested", amount = 500_000) {
  return { event_id: id, type, created: 1731920000,
    data: { refund_id: "rf_test", payment_id: "pay_test", amount, currency: "INR" } };
}
function signature(body: string | Uint8Array, time = Math.floor(Date.now() / 1000), secret = SECRET) {
  return `t=${time},v1=${computeSignature(secret, time, body)}`;
}
function snapshot(dir: string) {
  return Object.fromEntries(readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile()).map((entry) => {
      const path = join(entry.parentPath, entry.name);
      return [path, readFileSync(path, "utf8")];
    }));
}

test("rotation accepts any configured secret and signature candidate", () => {
