    for (const candidates of [["0".repeat(64), good], [good, "0".repeat(64)]]) {
      const header = `t=${now},${candidates.map((v) => `v1=${v}`).join(",")}`;
      assert.doesNotThrow(() => verifyWebhook(body, header, [SECRET, OLD_SECRET], now));
